

-- Handbook v1.14 remediation: distinct interpretation practice, client work, travel, and recovery events.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated business textconsecutive interpretingwarm-up' WHEN 1 THEN 'translated business textandproper nounslistening discrimination' WHEN 2 THEN 'translated business textretrospective'
      WHEN 3 THEN 'officialtranslated business textpractice' WHEN 4 THEN 'equipmenttranslated business text' WHEN 5 THEN 'clienttranslated business text'
      WHEN 6 THEN 'translated business text' WHEN 7 THEN 'confidential materialtranslated business text' WHEN 8 THEN 'Nanjingexam siteroutetranslated business text'
      WHEN 9 THEN 'Hangzhou Eaststationtranslated business textbuffer' WHEN 10 THEN 'hoteltranslated business textrulesverify' WHEN 11 THEN 'translated business textandtranslated business textitemtranslated business textordertranslated business text'
      WHEN 12 THEN 'voiceresttranslated business text' WHEN 13 THEN 'translated business textandtranslated business text' WHEN 14 THEN 'emailtranslated business text'
      WHEN 15 THEN 'equipmenttranslated business textquery' ELSE 'translated business textbeforeriskdaytranslated business textupdate' END AS event_topic,
    CASE rowid % 19
      WHEN 0 THEN 'practicenot exceedtranslated business text' WHEN 1 THEN 'after completionresttranslated business text' WHEN 2 THEN 'translated business textusepublicpractice materials' WHEN 3 THEN 'must notuseclienttranslated business text'
      WHEN 4 THEN 'must notandclientmeetingtranslated business text' WHEN 5 THEN 'translated business textbeforeaftertranslated business text' WHEN 6 THEN 'according toofficialnoticetranslated business textprevails' WHEN 7 THEN 'unauthorizedbeforetranslated business textticket'
      WHEN 8 THEN 'unauthorizedbeforetranslated business texthotel' WHEN 9 THEN 'voicetranslated business textintensity' WHEN 10 THEN 'do not maketranslated business textdiagnosis' WHEN 11 THEN 'after completionupdatestatusfile'
      WHEN 12 THEN 'translated business textretaintranslated business textbuffer' WHEN 13 THEN 'firstverifyequipmenttranslated business text' WHEN 14 THEN 'translated business textsendtranslated business textitemattachment' WHEN 15 THEN 'translated business text'
      WHEN 16 THEN 'translated business texttotranslated business textfirsttranslated business textLin Qiaoxi' WHEN 17 THEN 'retaintranslated business textarrangement' ELSE 'according totranslated business textqueryprevails' END AS event_constraint
  FROM events WHERE event_id LIKE 'CAL_INTERP_BG_%'
)
UPDATE events
SET summary=(SELECT event_topic FROM facts WHERE facts.rid=events.rowid),
    description=CASE rowid % 7
      WHEN 0 THEN (SELECT event_topic || 'alreadytranslated business text；' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 1 THEN (SELECT 'thistranslated business textsegmenttranslated business text' || event_topic || '，boundaryfor' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 2 THEN (SELECT event_constraint || '；translated business textis' || event_topic || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 3 THEN (SELECT 'oral examandtravelcoordinationitems：' || event_topic || '。' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 4 THEN (SELECT event_topic || 'andtranslated business textdayarrangementtranslated business text；' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 5 THEN (SELECT 'retaintranslated business textsegmenttranslated business text' || event_topic || '；translated business textchangetranslated business text' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      ELSE (SELECT event_topic || 'translated business textexistingtranslated business text，executerequirementis' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
    END,
    event_id=replace(event_id,'CAL_INTERP_BG_','CAL_INTERP_CONTEXT_')
WHERE event_id LIKE 'CAL_INTERP_BG_%';
